-- Выпуск 17 в журнале обновлений (ADR 0077): кабинет водителя после первого показа — крупный шрифт
-- в кабине, задание строго по документу и предупреждения во время ввода.
--
-- Схему миграция не трогает — она только заводит запись выпуска, как 0102, 0109, 0113, 0116, 0125,
-- 0126, 0128 и 0134 (ADR 0077 §4). Номер 0135 — следующий свободный за 0134.
--
-- Хвост версии — `0105`: единственное решение блока (ADR 0077 §2). Выпуск отдельный, а не подверсия
-- к 16-му, потому что ADR 0105 изменяет уже опубликованные 0102 и 0103: снаружи это не доделка
-- вчерашнего экрана, а другой ответ на вопрос «что водитель видит и что он вправе записать».
--
-- Правки шрифта, прокрутки и закреплённых кнопок стоят рядом с содержательными не как косметика:
-- кабинет читают с телефона в кабине, и цена промаха здесь — переписанная не та цифра.

INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  18, '0.1.17.0105', '2026-08-13', 'Кабинет водителя: задание по документу и подсказки при вводе', '{105}',
  '[
    {"kind":"improvement","text":"В задании остались только те выезды, по которым выписан действительный путевой лист на этого водителя: показания переносят в лист, и без бумаги их некуда класть. Рейс, где лист ещё не выписан или уже аннулирован, водитель не видит вовсе — а письмо с заданием накануне приходит как прежде, независимо от листа"},
    {"kind":"improvement","text":"При вводе портал показывает предыдущее показание счётчика и дату, когда его сняли, и предупреждает до отправки: значение ниже предыдущего или невероятный прирост требуют подтверждения — так бывает и правдой, если счётчик заменили или машина стояла. Явно невозможное число портал не принимает: это опечатка в разряде, подтверждать её нечем"},
    {"kind":"improvement","text":"Отметку «нет возможности снять показания» ставит теперь диспетчер, а не водитель: причину неввода записывает тот, кто её выяснял. Водителю нечего вводить — строка остаётся незаполненной, день висит в гараже как частичный, и закрывают его с причиной"},
    {"kind":"improvement","text":"Кабинет приведён к работе с телефона в кабине: крупный шрифт во всех экранах водителя, ни одной строки, уезжающей вбок, и кнопки передачи показаний закреплены внизу экрана — до них не нужно докручивать длинный список машин"}
  ]'::jsonb
);
